import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Recherche en texte intégral","description":"","frontmatter":{},"headers":[],"relativePath":"fr/advanced/search.md","filePath":"fr/advanced/search.md","lastUpdated":1784903584000}'),r={name:"fr/advanced/search.md"};function o(d,e,c,i,l,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="recherche-en-texte-integral" tabindex="-1">Recherche en texte intégral <a class="header-anchor" href="#recherche-en-texte-integral" aria-label="Permalink to &quot;Recherche en texte intégral&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>swag2mcp inclut un moteur de recherche en texte intégral intégré (bluge) qui indexe tous les points d&#39;accès de toutes les specs. Le LLM peut rechercher des points d&#39;accès par méthode, chemin, résumé ou étiquette — même sans connaître l&#39;ID du point d&#39;accès.</p><h2 id="comment-fonctionne-l-indexation" tabindex="-1">Comment fonctionne l&#39;indexation <a class="header-anchor" href="#comment-fonctionne-l-indexation" aria-label="Permalink to &quot;Comment fonctionne l&#39;indexation&quot;">​</a></h2><p>Lorsqu&#39;une spec est ajoutée ou mise à jour, chaque point d&#39;accès est indexé. Les champs suivants sont consultables :</p><table tabindex="0"><thead><tr><th>Champ</th><th>Description</th><th>Exemple</th></tr></thead><tbody><tr><td><code>method</code></td><td>Méthode HTTP</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code></td></tr><tr><td><code>path</code></td><td>Chemin du point d&#39;accès API</td><td><code>/api/v1/users/{id}</code></td></tr><tr><td><code>summary</code></td><td>Résumé OpenAPI</td><td>« Trouver un animal par ID »</td></tr><tr><td><code>tag</code></td><td>Catégorie du point d&#39;accès</td><td>« animaux », « utilisateurs »</td></tr><tr><td><code>_all</code></td><td>Tous les champs combinés</td><td>méthode + chemin + étiquette + résumé</td></tr></tbody></table><p>L&#39;index est reconstruit à chaque démarrage du serveur MCP. Il est stocké en mémoire pour des recherches rapides.</p><h2 id="syntaxe-de-requete" tabindex="-1">Syntaxe de requête <a class="header-anchor" href="#syntaxe-de-requete" aria-label="Permalink to &quot;Syntaxe de requête&quot;">​</a></h2><p>La recherche prend en charge une syntaxe de requête riche pour un filtrage précis :</p><table tabindex="0"><thead><tr><th>Exemple</th><th>Description</th></tr></thead><tbody><tr><td><code>animal</code></td><td>Recherche textuelle simple dans tous les champs</td></tr><tr><td><code>method:GET</code></td><td>Trouver tous les points d&#39;accès GET</td></tr><tr><td><code>tag:animaux</code></td><td>Trouver les points d&#39;accès dans l&#39;étiquette « animaux »</td></tr><tr><td><code>path:&quot;/api/v1/users&quot;</code></td><td>Correspondance exacte de chemin</td></tr><tr><td><code>+method:POST +tag:animal</code></td><td>Doit correspondre aux deux conditions</td></tr><tr><td><code>-method:DELETE</code></td><td>Exclure les méthodes DELETE</td></tr><tr><td><code>create~</code></td><td>Recherche floue (tolérante aux fautes de frappe)</td></tr><tr><td><code>cr*</code></td><td>Recherche par joker</td></tr><tr><td><code>&quot;trouver animal&quot;</code></td><td>Recherche par phrase</td></tr><tr><td><code>+summary:animal -method:DELETE</code></td><td>Inclure « animal » dans le résumé, exclure DELETE</td></tr></tbody></table><h3 id="recherche-par-champ-specifique" tabindex="-1">Recherche par champ spécifique <a class="header-anchor" href="#recherche-par-champ-specifique" aria-label="Permalink to &quot;Recherche par champ spécifique&quot;">​</a></h3><p>Vous pouvez rechercher dans des champs spécifiques en utilisant la syntaxe <code>champ:valeur</code> :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method:GET</span></span>
<span class="line"><span>tag:animaux</span></span>
<span class="line"><span>path:&quot;/animal/findByStatus&quot;</span></span>
<span class="line"><span>summary:&quot;trouver animal par statut&quot;</span></span></code></pre></div><h3 id="operateurs-booleens" tabindex="-1">Opérateurs booléens <a class="header-anchor" href="#operateurs-booleens" aria-label="Permalink to &quot;Opérateurs booléens&quot;">​</a></h3><ul><li><code>+</code> — le terme doit correspondre (ET)</li><li><code>-</code> — le terme ne doit pas correspondre (NON)</li><li>Espace entre les termes — OU (n&#39;importe quel terme peut correspondre)</li></ul><h3 id="recherche-floue-et-par-joker" tabindex="-1">Recherche floue et par joker <a class="header-anchor" href="#recherche-floue-et-par-joker" aria-label="Permalink to &quot;Recherche floue et par joker&quot;">​</a></h3><ul><li><code>terme~</code> — recherche floue (correspond à des mots similaires, gère les fautes de frappe)</li><li><code>te*</code> — joker (correspond à n&#39;importe quels caractères)</li><li><code>te?t</code> — joker pour un seul caractère</li></ul><h2 id="exemples" tabindex="-1">Exemples <a class="header-anchor" href="#exemples" aria-label="Permalink to &quot;Exemples&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Trouver toutes les requêtes GET</span></span>
<span class="line"><span>method:GET</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Trouver les requêtes POST dans l&#39;étiquette animal</span></span>
<span class="line"><span>+method:POST +tag:animal</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Trouver des points d&#39;accès par chemin exact</span></span>
<span class="line"><span>path:&quot;/animal/findByStatus&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Trouver par description</span></span>
<span class="line"><span>&quot;trouver animal par statut&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Trouver tout sauf DELETE</span></span>
<span class="line"><span>+summary:animal -method:DELETE</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Recherche floue pour « create » (gère les fautes de frappe)</span></span>
<span class="line"><span>create~</span></span></code></pre></div><h2 id="outil-mcp" tabindex="-1">Outil MCP <a class="header-anchor" href="#outil-mcp" aria-label="Permalink to &quot;Outil MCP&quot;">​</a></h2><p>L&#39;outil MCP <code>search</code> expose le moteur de recherche au LLM :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ search(query: &quot;trouver animal par statut&quot;, limit: 5)</span></span>
<span class="line"><span>← GET /animal/findByStatus — Trouve les animaux par statut</span></span>
<span class="line"><span>   GET /animal/{animalId} — Trouver un animal par ID</span></span></code></pre></div><h3 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Paramètre</th><th>Requis</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>Oui</td><td>Requête de recherche (prend en charge la syntaxe structurée)</td></tr><tr><td><code>limit</code></td><td>Oui</td><td>Nombre maximum de résultats (1-50)</td></tr></tbody></table><h2 id="notes-importantes" tabindex="-1">Notes importantes <a class="header-anchor" href="#notes-importantes" aria-label="Permalink to &quot;Notes importantes&quot;">​</a></h2><ul><li><strong>L&#39;index est en mémoire</strong> — il est reconstruit à chaque démarrage du serveur MCP. Il n&#39;y a pas de fichier d&#39;index persistant.</li><li><strong>Tous les champs sont en minuscules</strong> — les recherches sont insensibles à la casse</li><li><strong>La limite est plafonnée à 50</strong> — vous ne pouvez pas demander plus de 50 résultats</li><li><strong>Une syntaxe de requête invalide</strong> retourne un message d&#39;erreur utile avec des exemples</li><li><strong>Le champ <code>_all</code></strong> combine méthode, chemin, étiquette et résumé pour les recherches textuelles simples</li></ul>`,26)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
